INSERT INTO feature VALUES('generic-programs','descriptions','Generic programs over descriptions','signatures-as-values','implemented','uncommon','mainstream languages','An ordinary function reads any presentation by case, and a function returning type codes is read as a type. A definition written `Eq.generic(T)` is structural equality over the data declaration `T`''s constructors, derived from its levitated code and checked as any declaration, so a model of `Eq` puts `T` under `==`; a field with no equality is refused by name, and a declaration with parameters, a nested or mutual recursion, or a dependent field is not yet covered (#2345).','surface-lowering core-term core-checker','corpus/model/desc/generic-arity.gandr corpus/model/desc/derive-eq-serialize.gandr corpus/model/desc/generic-arity-behind.gandr corpus/model/data/data-generic-eq.gandr corpus/pathological/data/generic-eq-refused.gandr','corpus/model/desc/generic-arity.gandr',NULL);
